// MSG-01 Integration Inspection Note:
// MSG-01 (ZALO-01) persists state strictly in n8n internal staticData ($getWorkflowStaticData)
// and outputs alerts directly to Telegram. It lacks an external DB, message bus, or query webhook.
// Per OPS-01 Phase 1 requirements, this limitation is documented and we proceed with clean structured output.
return [{
  json: {
    source: 'MSG-01',
    status: 'NO_REUSABLE_PERSISTED_OUTPUT',
    items: [],
    limitation: 'MSG-01 stores triage state in workflow-internal staticData; no external DB or subworkflow trigger available without modifying MSG-01 logic.'
  }
}];

const now = new Date();
const dateStr = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Ho_Chi_Minh',
  day: '2-digit',
  month: 'short'
}).format(now);

// 1. Calendar normalization
let rawCalendar = [];
try {
  rawCalendar = $('Get Today\'s Calendar').all();
} catch (e) {
  rawCalendar = [];
}

const calendar = [];
for (const item of rawCalendar) {
  const j = item.json ?? {};
  if (!j.summary && !j.id && !j.start) continue;
  if (j.error) continue;

  const title = j.summary ?? j.title ?? 'Untitled Event';
  const start = j.start?.dateTime ?? j.start?.date ?? j.start ?? '';
  const end = j.end?.dateTime ?? j.end?.date ?? j.end ?? '';
  const location = j.location ?? '';
  const description = j.description ? String(j.description).slice(0, 300) : '';
  const status = j.status ?? 'confirmed';
  const attendees = Array.isArray(j.attendees)
    ? j.attendees.map(a => a.displayName || a.email).filter(Boolean).slice(0, 5)
    : [];

  calendar.push({
    title,
    start,
    end,
    location,
    description,
    status,
    attendees
  });
}

calendar.sort((a, b) => String(a.start).localeCompare(String(b.start)));

// 2. Email normalization
let rawEmail = [];
try {
  rawEmail = $('Get Recent Gmail').all();
} catch (e) {
  rawEmail = [];
}

const email = [];
let ignoredCount = 0;

for (const item of rawEmail) {
  const j = item.json ?? {};
  if (!j.id && !j.threadId && !j.snippet && !j.subject) continue;
  if (j.error) continue;

  const headers = j.headers || j.payload?.headers || {};
  let sender = j.from || headers.from || '';
  let subject = j.subject || headers.subject || '';
  const snippet = j.snippet || j.text || (typeof j.body === 'string' ? j.body.slice(0, 300) : '');
  const receivedAt = j.internalDate ? new Date(Number(j.internalDate)).toISOString() : (j.date || headers.date || new Date().toISOString());
  const messageId = j.id || '';
  const threadId = j.threadId || '';

  sender = String(sender).replace(/[<>]/g, '').trim();

  const lowerSubj = (subject + ' ' + sender + ' ' + snippet).toLowerCase();
  const isSpammy = lowerSubj.includes('unsubscribe') || 
                   lowerSubj.includes('newsletter') || 
                   lowerSubj.includes('no-reply@') || 
                   lowerSubj.includes('noreply@') || 
                   lowerSubj.includes('promotional');

  if (isSpammy && !lowerSubj.includes('invoice') && !lowerSubj.includes('payment') && !lowerSubj.includes('urgent')) {
    ignoredCount++;
    continue;
  }

  email.push({
    sender,
    subject,
    received_at: receivedAt,
    snippet: snippet ? snippet.slice(0, 250) : '',
    message_id: messageId,
    thread_id: threadId
  });
}

// 3. Messages normalization (MSG-01)
let rawMessages = [];
try {
  const msgSummary = $('Get MSG-01 Summary').first()?.json ?? {};
  rawMessages = Array.isArray(msgSummary.items) ? msgSummary.items : [];
} catch (e) {
  rawMessages = [];
}

const messages = rawMessages.map(m => ({
  sender: m.sender_name || m.sender || 'Unknown',
  text: (m.text || m.content || '').slice(0, 250),
  timestamp: m.timestamp || '',
  lane: m.lane || '',
  intent: m.intent || ''
}));

return [{
  json: {
    generated_at: now.toISOString(),
    date: dateStr,
    calendar,
    email,
    messages,
    stats: {
      calendar_count: calendar.length,
      email_count: email.length,
      messages_count: messages.length,
      prefiltered_count: ignoredCount
    }
  }
}];

function sanitizeTelegramHtml(text) {
  if (!text) return '';
  // Match allowed Telegram tags
  const tokens = [];
  const tokenized = String(text).replace(/<\/?(b|i|code|s|u|pre|a)(?:\s+[^>]+)?>/gi, (match) => {
    tokens.push(match);
    return '___TAG_TOKEN_' + (tokens.length - 1) + '___';
  });

  let escaped = tokenized
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  escaped = escaped.replace(/___TAG_TOKEN_(\d+)___/g, (_, i) => tokens[Number(i)]);
  return escaped.trim();
}

const raw = $json.text ?? $json.output ?? '';
const telegramText = sanitizeTelegramHtml(raw);

return [{
  json: {
    ...$json,
    telegram_text: telegramText
  }
}];
